"{\n"
"        $key = ws_request_key($head);\n"
"        if ($key == \"\") {\n"
"            stream_send($this->socks[$id], ws_reject_respons"
"e());\n"
"            $this->drop($id, 1002);\n"
"            return false;\n"
"        }\n"
"        $sent = stream_send($this->socks[$id], ws_upgrade_re"
"sponse($key));\n"
"        if ($sent <= 0) { $this->drop($id, 1011); return fal"
"se; }\n"
"        return true;\n"
"    }\n"
"\n"
"    /* Decode every complete frame currently buffered. */\n"
"    private function pumpFrames(int $id): void {\n"
"        while (true) {\n"
"            if (!$this->isOpen($id)) { return; }\n"
"            $buf = $this->bufs[$id];\n"
"            $f = ws_decode($buf);\n"
"            if ($f == null) { return; }\n"
"            $this->bufs[$id] = substr($buf, $f[\"consumed\"]);"
"\n"
"            $op = $f[\"opcode\"];\n"
"            $payload = $f[\"payload\"];\n"
"\n"
"            if ($op == 0) {                       /* continu"
"ation */\n"
"                $this->frags[$id] = $this->frags[$id] . $pay"
"load;\n"
"                if ($f[\"fin\"]) {\n"
"                    $whole = $this->frags[$id];\n"
"                    $this->frags[$id] = \"\";\n"
"                    $this->deliver($id, $this->fragOps[$id],"
" $whole);\n"
"                }\n"
"                continue;\n"
"            }\n"
"            if ($op == 1 || $op == 2) {           /* text / "
"binary */\n"
"                if ($f[\"fin\"]) {\n"
"                    $this->deliver($id, $op, $payload);\n"
"                } else {\n"
"                    $this->frags[$id] = $payload;\n"
"                    $this->fragOps[$id] = $op;\n"
"                }\n"
"                continue;\n"
"            }\n"
"            if ($op == 8) {                       /* close *"
"/\n"
"                $this->drop($id, 1000);\n"
"                return;\n"
"            }\n"
"            if ($op == 9) {                       /* ping ->"
" pong */\n"
"                stream_send($this->socks[$id], ws_frame($pay"
"load, 10));\n"
"                continue;\n"
"            }\n"
"            /* 10 = pong: nothing to do */\n"
"        }\n"
"    }\n"
"\n"
"    private function deliver(int $id, int $op, string $paylo"
"ad): void {\n"
"        if ($op == 2) {\n"
"            if ($this->onBinary != null) { $this->onBinary($"
"id, $payload); }\n"
"            return;\n"
"        }\n"
"        if ($this->onMessage != null) { $this->onMessage($id"
", $payload); }\n"
"    }\n"
"}\n"
;

